CREATE OR REFRESH MATERIALIZED VIEW silver_live_events
COMMENT 'Live events de-duplicated on event id, earliest arrival kept, with a late flag.'
TBLPROPERTIES ('quality' = 'silver', 'contains_pii' = 'false')
AS
WITH ranked AS (
  SELECT *, row_number() OVER (PARTITION BY event_id ORDER BY ingested_at, source_file) AS rn
  FROM bronze_live_events
  WHERE event_id IS NOT NULL AND event_dt IS NOT NULL AND wiki IS NOT NULL
),
batches AS (
  SELECT source_file, stream, min(ingested_at) AS batch_at, min(event_dt) AS batch_min_dt,
         max(event_dt) AS batch_max_dt
  FROM bronze_live_events
  GROUP BY source_file, stream
),
wm AS (
  SELECT source_file, stream,
         max(batch_max_dt) OVER (PARTITION BY stream ORDER BY batch_at, batch_min_dt, source_file
                                 ROWS BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING) AS watermark_dt
  FROM batches
)
SELECT r.event_id, r.event_dt, r.stream, r.wiki, r.event_type, r.namespace, r.page_id,
       r.page_title, r.rev_id, r.is_bot, r.is_redirect, r.length_new, r.editor_hash,
       r.source_file, r.ingested_at,
       CASE WHEN w.watermark_dt IS NOT NULL
             AND unix_timestamp(r.event_dt) < unix_timestamp(w.watermark_dt) - 600 THEN true ELSE false END AS is_late
FROM ranked r
JOIN wm w ON r.source_file = w.source_file AND r.stream = w.stream
WHERE r.rn = 1;

CREATE OR REFRESH MATERIALIZED VIEW gold_live_activity
COMMENT 'Live activity per wiki in 15-minute event-time windows; late events counted apart.'
TBLPROPERTIES ('quality' = 'gold', 'contains_pii' = 'false')
AS
SELECT timestamp_seconds(CAST(floor(unix_timestamp(event_dt) / 900) AS BIGINT) * 900) AS window_start,
       wiki,
       CAST(sum(CASE WHEN NOT is_late THEN 1 ELSE 0 END) AS BIGINT) AS events,
       CAST(sum(CASE WHEN is_late THEN 1 ELSE 0 END) AS BIGINT) AS late_events,
       CAST(sum(CASE WHEN NOT is_late AND coalesce(is_bot, false) THEN 1 ELSE 0 END) AS BIGINT) AS bot_events,
       CAST(sum(CASE WHEN NOT is_late AND NOT coalesce(is_bot, false) AND namespace = 0
                 AND event_type IN ('edit', 'new') THEN 1 ELSE 0 END) AS BIGINT) AS human_article_edits,
       CAST(sum(CASE WHEN NOT is_late AND NOT coalesce(is_bot, false) AND namespace = 0
                 AND event_type = 'page-create' AND NOT coalesce(is_redirect, false)
            THEN 1 ELSE 0 END) AS BIGINT) AS new_articles
FROM silver_live_events
GROUP BY timestamp_seconds(CAST(floor(unix_timestamp(event_dt) / 900) AS BIGINT) * 900), wiki;

CREATE OR REFRESH MATERIALIZED VIEW gold_coverage_lag
COMMENT 'Coverage lag per item and language, the core metric (docs/method.md).'
TBLPROPERTIES ('quality' = 'gold', 'contains_pii' = 'false')
AS
WITH eligible AS (
  SELECT s.item_id, c.wiki, c.created_at
  FROM silver_page_creations c
  JOIN silver_sitelinks s ON s.wiki = c.wiki AND s.page_title = c.page_title
  WHERE NOT c.is_redirect AND NOT c.is_deleted AND NOT c.created_by_bot
),
firsts AS (
  SELECT item_id, min(created_at) AS first_created_at, CAST(count(*) AS BIGINT) AS languages
  FROM eligible
  GROUP BY item_id
)
SELECT e.item_id, e.wiki, e.created_at, f.first_created_at, f.languages,
       CAST(unix_timestamp(e.created_at) - unix_timestamp(f.first_created_at) AS BIGINT) AS lag_seconds,
       CASE WHEN e.created_at = f.first_created_at THEN true ELSE false END AS is_first,
       'slice20' AS reference_set
FROM eligible e
JOIN firsts f ON e.item_id = f.item_id;

CREATE OR REFRESH MATERIALIZED VIEW gold_language_lag
COMMENT 'Per language, items covered, items created first and median coverage lag.'
TBLPROPERTIES ('quality' = 'gold', 'contains_pii' = 'false')
AS
SELECT wiki,
       CAST(count(*) AS BIGINT) AS items_covered,
       CAST(sum(CASE WHEN is_first THEN 1 ELSE 0 END) AS BIGINT) AS items_first,
       CAST(sum(CASE WHEN languages >= 2 AND NOT is_first THEN 1 ELSE 0 END) AS BIGINT) AS items_followed,
       CAST(median(CASE WHEN languages >= 2 AND NOT is_first THEN lag_seconds END) AS DOUBLE)
         / 86400.0
         AS median_lag_days,
       (SELECT CAST(count(DISTINCT item_id) AS BIGINT) FROM gold_coverage_lag) AS items_in_reference
FROM gold_coverage_lag
GROUP BY wiki;

CREATE OR REFRESH MATERIALIZED VIEW gold_item_pageviews
COMMENT 'Human pageviews per item, language and day for the slice days.'
TBLPROPERTIES ('quality' = 'gold', 'contains_pii' = 'false')
AS
SELECT p.wiki, s.item_id, p.day, CAST(sum(p.views) AS BIGINT) AS views
FROM silver_pageviews_daily p
JOIN silver_sitelinks s ON s.wiki = p.wiki AND s.page_title = p.page_title
GROUP BY p.wiki, s.item_id, p.day;
